import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FiSearch, FiShoppingCart, FiUser, FiHeart, FiMenu, FiX, FiChevronDown, FiMapPin } from 'react-icons/fi';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useCart } from '../contexts/CartContext';

const Header = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [profileDropdown, setProfileDropdown] = useState(false);
  const { user, seller, admin, isAuthenticated, logout, sellerLogout } = useAuth();
  const { totalItems } = useCart();
  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchQuery.trim())}`);
    }
  };

  const handleLogout = () => {
    if (seller) {
      sellerLogout();
      navigate('/seller/login');
    } else {
      logout();
      navigate('/');
    }
    setProfileDropdown(false);
  };

  const categories = [
    { name: 'Sunglasses', path: '/category/sunglasses' },
    { name: 'Eyeglasses', path: '/category/eyeglasses' },
    { name: 'Contact Lenses', path: '/category/contact-lenses' },
    { name: 'Computer Glasses', path: '/category/computer-glasses' },
    { name: 'Sports Eyewear', path: '/category/sports-eyewear' },
  ];

  return (
    <header style={{ background: 'var(--bg-dark)', position: 'sticky', top: 0, zIndex: 50 }}>
      <div className="container" style={{ display: 'flex', alignItems: 'center', height: 'var(--header-height)', gap: '16px' }}>
        <Link to="/" style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', minWidth: 'fit-content' }}>
          <span style={{ color: 'var(--secondary)', fontSize: '20px', fontWeight: 700, letterSpacing: '-0.5px' }}>OptiKart</span>
          <span style={{ color: '#999', fontSize: '10px', fontStyle: 'italic', display: 'flex', alignItems: 'center', gap: '2px' }}>
            Explore <span style={{ color: 'var(--secondary)' }}>Plus</span> <span style={{ fontSize: '8px' }}>✦</span>
          </span>
        </Link>

        <form onSubmit={handleSearch} style={{ flex: 1, maxWidth: '560px', position: 'relative' }}>
          <input
            type="text"
            placeholder="Search for sunglasses, eyeglasses, contact lenses and more"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{
              width: '100%',
              padding: '10px 16px 10px 40px',
              borderRadius: '4px',
              border: 'none',
              fontSize: '14px',
              background: '#fff',
              color: 'var(--text-primary)',
            }}
          />
          <FiSearch style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--primary)', fontSize: '18px' }} />
        </form>

        <nav className="hide-mobile" style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
          {isAuthenticated ? (
            <div style={{ position: 'relative' }}>
              <button
                onClick={() => setProfileDropdown(!profileDropdown)}
                style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#fff', fontSize: '14px', fontWeight: 500 }}
              >
                <FiUser size={18} />
                <span>{user?.name || seller?.businessName || 'Account'}</span>
                <FiChevronDown size={14} />
              </button>
              <AnimatePresence>
                {profileDropdown && (
                  <motion.div
                    initial={{ opacity: 0, y: -8 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -8 }}
                    style={{
                      position: 'absolute',
                      top: '100%',
                      right: 0,
                      marginTop: '8px',
                      background: '#fff',
                      borderRadius: '4px',
                      boxShadow: 'var(--shadow-lg)',
                      minWidth: '200px',
                      zIndex: 100,
                      overflow: 'hidden',
                    }}
                  >
                    {user && (
                      <>
                        <Link to="/profile" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>My Profile</Link>
                        <Link to="/orders" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>Orders</Link>
                        <Link to="/wishlist" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>Wishlist</Link>
                      </>
                    )}
                    {seller && (
                      <>
                        <Link to="/seller/dashboard" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>Dashboard</Link>
                        <Link to="/seller/products" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>Products</Link>
                        <Link to="/seller/orders" onClick={() => setProfileDropdown(false)} style={{ display: 'block', padding: '12px 16px', fontSize: '14px', color: 'var(--text-primary)', borderBottom: '1px solid var(--border)' }}>Orders</Link>
                      </>
                    )}
                    <button onClick={handleLogout} style={{ display: 'block', width: '100%', textAlign: 'left', padding: '12px 16px', fontSize: '14px', color: 'var(--danger)' }}>Logout</button>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ) : (
            <Link to="/login" style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#fff', fontSize: '14px', fontWeight: 600, padding: '6px 24px', background: '#fff', borderRadius: '4px' }}>
              <FiUser size={16} />
              Login
            </Link>
          )}

          <Link to="/wishlist" style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#fff', fontSize: '14px', fontWeight: 500 }}>
            <FiHeart size={18} />
          </Link>

          <Link to="/cart" style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#fff', fontSize: '14px', fontWeight: 500, position: 'relative' }}>
            <FiShoppingCart size={18} />
            {totalItems > 0 && (
              <span style={{ position: 'absolute', top: '-8px', right: '-8px', background: 'var(--secondary)', color: 'var(--text-primary)', fontSize: '10px', fontWeight: 700, width: '18px', height: '18px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {totalItems}
              </span>
            )}
            Cart
          </Link>
        </nav>

        <button className="hide-desktop" onClick={() => setMobileMenuOpen(!mobileMenuOpen)} style={{ color: '#fff', fontSize: '24px', marginLeft: 'auto' }}>
          {mobileMenuOpen ? <FiX /> : <FiMenu />}
        </button>
      </div>

      <div className="hide-mobile" style={{ background: '#fff', borderTop: '1px solid var(--border)' }}>
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: '32px', height: '40px', overflow: 'hidden' }}>
          {categories.map((cat) => (
            <Link key={cat.path} to={cat.path} style={{ fontSize: '14px', fontWeight: 500, color: 'var(--text-primary)', whiteSpace: 'nowrap' }}>
              {cat.name}
            </Link>
          ))}
          <Link to="/brands" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--text-primary)' }}>All Brands</Link>
          <Link to="/virtual-tryon" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--primary)' }}>Virtual Try-On</Link>
          <Link to="/prescription" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--text-primary)' }}>Upload Prescription</Link>
          <Link to="/coupons" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--secondary)' }}>Offers</Link>
          <Link to="/blog" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--text-primary)' }}>Blog</Link>
          <Link to="/help" style={{ fontSize: '14px', fontWeight: 500, color: 'var(--text-primary)' }}>Help</Link>
        </div>
      </div>

      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            style={{ background: '#fff', overflow: 'hidden', position: 'absolute', width: '100%', zIndex: 99 }}
          >
            <div style={{ padding: '16px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {categories.map((cat) => (
                <Link key={cat.path} to={cat.path} onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', fontWeight: 500, padding: '8px 0', borderBottom: '1px solid var(--border-light)' }}>
                  {cat.name}
                </Link>
              ))}
              <Link to="/brands" onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', padding: '8px 0' }}>All Brands</Link>
              <Link to="/virtual-tryon" onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', padding: '8px 0', color: 'var(--primary)' }}>Virtual Try-On</Link>
              <Link to="/cart" onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', padding: '8px 0' }}>Cart ({totalItems})</Link>
              <Link to="/wishlist" onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', padding: '8px 0' }}>Wishlist</Link>
              {!isAuthenticated && (
                <Link to="/login" onClick={() => setMobileMenuOpen(false)} style={{ fontSize: '14px', padding: '10px', background: 'var(--primary)', color: '#fff', borderRadius: '4px', textAlign: 'center', fontWeight: 600 }}>Login / Register</Link>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};

export default Header;
